import net.runelite.client.util.Text;

@Slf4j
@PluginDescriptor(
		name = "MLM QOL",
		description = "Quality of life for the Motherlode Mine: stop mining when the sack is full, and flag a stopped hopper",
		tags = {"motherlode", "mlm", "mining", "sack", "pay", "dirt", "skilling", "sound", "afk", "idle"},
		configName = "MlmQolPlugin"
)
public class MlmQolPlugin extends Plugin
{
	static final String CONFIG_GROUP = "mlm-qol";

	private static final Set<Integer> MOTHERLODE_MAP_REGIONS = ImmutableSet.of(14679, 14680, 14681, 14935, 14936, 14937, 15191, 15192, 15193);
	private static final Set<Integer> ORE_VEINS = ImmutableSet.of(ObjectID.MOTHERLODE_ORE_SINGLE, ObjectID.MOTHERLODE_ORE_LEFT,
		ObjectID.MOTHERLODE_ORE_MIDDLE, ObjectID.MOTHERLODE_ORE_RIGHT);
	private static final Set<MenuAction> OBJECT_OPTIONS = ImmutableSet.of(MenuAction.GAME_OBJECT_FIRST_OPTION,
		MenuAction.GAME_OBJECT_SECOND_OPTION, MenuAction.GAME_OBJECT_THIRD_OPTION, MenuAction.GAME_OBJECT_FOURTH_OPTION,
		MenuAction.GAME_OBJECT_FIFTH_OPTION);
	/**
	 * Clicks that send the player off to do something else, and so stop mining on purpose: walking,
	 * and interacting with an object, NPC, ground item or player. Interface clicks are deliberately
	 * absent — eating, dropping or switching tabs doesn't stop you mining — and so are Examine and
	 * Cancel, which send nothing at all. Using an inventory item on something in the world arrives as
	 * the WIDGET_TARGET_ON_* action; the ITEM_USE_ON_* pairs are deprecated and no longer produced.
	 */
	private static final Set<MenuAction> MANUAL_STOP_ACTIONS = ImmutableSet.<MenuAction>builder()
		.addAll(OBJECT_OPTIONS)
		.add(MenuAction.WALK)
		.add(MenuAction.WIDGET_TARGET_ON_GAME_OBJECT)
		.add(MenuAction.NPC_FIRST_OPTION, MenuAction.NPC_SECOND_OPTION, MenuAction.NPC_THIRD_OPTION,
			MenuAction.NPC_FOURTH_OPTION, MenuAction.NPC_FIFTH_OPTION)
		.add(MenuAction.WIDGET_TARGET_ON_NPC)
		.add(MenuAction.GROUND_ITEM_FIRST_OPTION, MenuAction.GROUND_ITEM_SECOND_OPTION,
			MenuAction.GROUND_ITEM_THIRD_OPTION, MenuAction.GROUND_ITEM_FOURTH_OPTION,
			MenuAction.GROUND_ITEM_FIFTH_OPTION)
		.add(MenuAction.WIDGET_TARGET_ON_GROUND_ITEM)
		.add(MenuAction.PLAYER_FIRST_OPTION, MenuAction.PLAYER_SECOND_OPTION, MenuAction.PLAYER_THIRD_OPTION,
			MenuAction.PLAYER_FOURTH_OPTION, MenuAction.PLAYER_FIFTH_OPTION, MenuAction.PLAYER_SIXTH_OPTION,
			MenuAction.PLAYER_SEVENTH_OPTION, MenuAction.PLAYER_EIGHTH_OPTION)
		.add(MenuAction.WIDGET_TARGET_ON_PLAYER)
		.build();
	/**
	 * The baby mole pet, plus the baby mole NPCs that share its look. Only ever matched while in the
	 * mine, so a pet being renamed anywhere else is not possible.
	 */
	private static final Set<Integer> BABY_MOLES = ImmutableSet.of(NpcID.MOLE_PET, NpcID.MOLE_PET_NAKED,
		NpcID.MOLE_BABY_01, NpcID.MOLE_BABY_02, NpcID.MOLE_BABY_03);

	private static final String MINE_OPTION = "Mine";
	private static final String DEPOSIT_OPTION = "Deposit";
	/** One strut per water wheel. The belt only stops when every one of them is broken. */
	private static final int STRUT_COUNT = 2;

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private ChatMessageManager chatMessageManager;

	@Inject
	private ConfigManager configManager;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private HopperOverlay hopperOverlay;

	@Inject
	private BabyMoleOverlay babyMoleOverlay;

	@Inject
	private MlmQolConfig config;

	@Inject
	private WakeUpSound wakeUpSound;

	private final SackTracker sackTracker = new SackTracker();
	private final MiningIdleTracker miningIdleTracker = new MiningIdleTracker();

	@Getter(AccessLevel.PACKAGE)
	private final Set<TileObject> hoppers = new HashSet<>();
	@Getter(AccessLevel.PACKAGE)
	private final Set<TileObject> brokenStruts = new HashSet<>();
	private final Set<TileObject> workingStruts = new HashSet<>();
	@Getter(AccessLevel.PACKAGE)
	private final Set<NPC> babyMoles = new HashSet<>();

	private boolean inMlm;
	private boolean sackFull;
	private boolean machineryStopped;

	@Provides
	MlmQolConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(MlmQolConfig.class);
	}

	@Override
	protected void startUp()
	{
		overlayManager.add(hopperOverlay);
		overlayManager.add(babyMoleOverlay);
		wakeUpSound.start();

		clientThread.invokeLater(() ->
		{
			inMlm = checkInMlm();
			if (inMlm)
			{
				primeTracker();
				// Spawn events for the scene we're already standing in have long since fired.
				scanScene();
			}
			// Adopt the current state silently so enabling the plugin doesn't spam a warning. This has
			// to settle before following the upgrade, since writing config re-evaluates the state.
			sackFull = inMlm && sackTracker.isFull(config.blockAtCount());

			// Not gated on being in the mine: the upgrade is readable from anywhere, and the plugin
			// usually starts up at the login screen.
			sackTracker.refreshCapacity(client);
			followCapacityUpgrade();
		});
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(hopperOverlay);
		overlayManager.remove(babyMoleOverlay);
		wakeUpSound.shutDown();
		inMlm = false;
		sackFull = false;
		sackTracker.reset();
		miningIdleTracker.reset();
		clearSceneObjects();
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		GameState gameState = event.getGameState();
		if (gameState == GameState.LOADING)
		{
			// On region changes the tracked objects get set to null.
			clearSceneObjects();
			// A swing left half-finished by the hop out must not alert on arrival.
			miningIdleTracker.reset();

			boolean wasInMlm = inMlm;
			inMlm = checkInMlm();
			if (inMlm && !wasInMlm)
			{
				// Anything tracked from a previous visit is stale — start over.
				primeTracker();
				followCapacityUpgrade();
				updateSackFull();
			}
		}
		else if (gameState == GameState.LOGGED_IN)
		{
			// Backstop for the varbit handler: re-logging in the same client session doesn't change
			// the varp, so no VarbitChanged fires and the upgrade would otherwise go unnoticed.
			sackTracker.refreshCapacity(client);
			followCapacityUpgrade();
		}
		else if (gameState == GameState.LOGIN_SCREEN)
		{
			inMlm = false;
			sackFull = false;
			sackTracker.reset();
			miningIdleTracker.reset();
			clearSceneObjects();
		}
	}

	// The mine mixes object types — the ore veins are wall objects, for instance — so the hopper and
	// struts are tracked from every spawn event rather than assuming which kind they are.

	@Subscribe
	public void onGameObjectSpawned(GameObjectSpawned event)
	{
		trackObject(event.getGameObject());
	}

	@Subscribe
	public void onGameObjectDespawned(GameObjectDespawned event)
	{
		untrackObject(event.getGameObject());
	}

	@Subscribe
	public void onWallObjectSpawned(WallObjectSpawned event)
	{
		trackObject(event.getWallObject());
	}

	@Subscribe
	public void onWallObjectDespawned(WallObjectDespawned event)
	{
		untrackObject(event.getWallObject());
	}

	@Subscribe
	public void onDecorativeObjectSpawned(DecorativeObjectSpawned event)
	{
		trackObject(event.getDecorativeObject());
	}

	@Subscribe
	public void onDecorativeObjectDespawned(DecorativeObjectDespawned event)
	{
		untrackObject(event.getDecorativeObject());
	}

	@Subscribe
	public void onGroundObjectSpawned(GroundObjectSpawned event)
	{
		trackObject(event.getGroundObject());
	}

	@Subscribe
	public void onGroundObjectDespawned(GroundObjectDespawned event)
	{
		untrackObject(event.getGroundObject());
	}

	@Subscribe
	public void onNpcSpawned(NpcSpawned event)
	{
		if (inMlm && BABY_MOLES.contains(event.getNpc().getId()))
		{
			babyMoles.add(event.getNpc());
		}
	}

	@Subscribe
	public void onNpcDespawned(NpcDespawned event)
	{
		babyMoles.remove(event.getNpc());
	}

	@Subscribe
	public void onAnimationChanged(AnimationChanged event)
	{
		if (!inMlm || event.getActor() != client.getLocalPlayer())
		{
			return;
		}

		miningIdleTracker.onAnimationChanged(event.getActor().getAnimation());
	}

	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked event)
	{
		// Stopping on purpose is not worth an alert, so a click elsewhere drops the swing being watched.
		if (inMlm && MANUAL_STOP_ACTIONS.contains(event.getMenuAction()))
		{
			miningIdleTracker.onManualStop();
		}
	}

	private void trackObject(TileObject object)
	{
		if (!inMlm || object == null)
		{
			return;
		}

		switch (object.getId())
		{
			case ObjectID.MOTHERLODE_HOPPER:
				hoppers.add(object);
				break;
			case ObjectID.MOTHERLODE_WHEEL_STRUT_BROKEN:
				brokenStruts.add(object);
				updateMachineryState();
				break;
			case ObjectID.MOTHERLODE_WHEEL_STRUT_FIXED:
				workingStruts.add(object);
				updateMachineryState();
				break;
		}
	}

	private void untrackObject(TileObject object)
	{
		if (!inMlm || object == null)
		{
			return;
		}

		hoppers.remove(object);

		boolean wasStrut = brokenStruts.remove(object);
		wasStrut |= workingStruts.remove(object);
		if (wasStrut)
		{
			updateMachineryState();
		}
	}

	/**
	 * Picks up the hopper and struts from the loaded scene. Only run when the plugin is enabled
	 * mid-session, since after that the spawn and despawn events keep the sets current.
	 */
	private void scanScene()
	{
		WorldView worldView = client.getTopLevelWorldView();
		if (worldView == null)
		{
			return;
		}

		for (Tile[][] plane : worldView.getScene().getTiles())
		{
			for (Tile[] column : plane)
			{
				for (Tile tile : column)
				{
					if (tile == null)
					{
						continue;
					}

					for (GameObject gameObject : tile.getGameObjects())
					{
						trackObject(gameObject);
					}

					trackObject(tile.getWallObject());
					trackObject(tile.getDecorativeObject());
					trackObject(tile.getGroundObject());
				}
			}
		}

		for (NPC npc : worldView.npcs())
		{
			if (BABY_MOLES.contains(npc.getId()))
			{
				babyMoles.add(npc);
			}
		}
	}

	@Subscribe
	public void onVarbitChanged(VarbitChanged event)
	{
		// The upgrade varbit is only transmitted during the login varp sync, long before the player is
		// anywhere near the mine, so this must not be gated on inMlm.
		if (event.getVarbitId() == VarbitID.MOTHERLODE_BIGGERSACK)
		{
			sackTracker.refreshCapacity(client);
			followCapacityUpgrade();
		}

		if (!inMlm)
		{
			return;
		}

		if (event.getVarbitId() == VarbitID.MOTHERLODE_SACK_TRANSMIT || event.getVarbitId() == VarbitID.MOTHERLODE_BIGGERSACK)
		{
			sackTracker.refreshSack(client);
			updateSackFull();
		}
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (CONFIG_GROUP.equals(event.getGroup()))
		{
			updateSackFull();
		}
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		if (!inMlm || event.getContainerId() != InventoryID.INV)
		{
			return;
		}

		sackTracker.refreshInventory(client);
		updateSackFull();
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		if (!inMlm)
		{
			return;
		}

		// The write-off assumes pay-dirt that never arrives was never deposited. A stopped belt is a
		// legitimate long gap, so don't let it discard pay-dirt that is genuinely stranded out there.
		if (!machineryStopped)
		{
			sackTracker.onTick();
		}

		updateSackFull();
		checkMiningStopped();
	}

	@Subscribe
	public void onMenuEntryAdded(MenuEntryAdded event)
	{
		if (!inMlm)
		{
			return;
		}

		MenuEntry entry = event.getMenuEntry();
		if (!OBJECT_OPTIONS.contains(entry.getType()))
		{
			return;
		}

		int objectId = event.getIdentifier();
		String option = Text.removeTags(entry.getOption());

		// Nothing to mine into once the sack is at its block count.
		if (ORE_VEINS.contains(objectId) && MINE_OPTION.equals(option) && sackFull && config.blockMining())
		{
			client.getMenu().removeMenuEntry(entry);
			return;
		}

		// Nowhere for it to go: the belt is stopped and the sack has no room for another load.
		if (objectId == ObjectID.MOTHERLODE_HOPPER && DEPOSIT_OPTION.equals(option) && isDepositBlocked())
		{
			client.getMenu().removeMenuEntry(entry);
		}
	}

	/**
	 * Two things stop another load going in, and either is enough: pay-dirt already stranded on the
	 * stopped belt, or a sack with no room left for it. Pay-dirt in the inventory counts towards
	 * neither — that is the load asking to be deposited, not something in its way.
	 */
	private boolean isDepositBlocked()
	{
		// Only a stopped belt makes a deposit pointless. While it runs, pay-dirt on it is on its way
		// out and the sack will have room again shortly.
		if (!config.blockDepositWhenBlocked() || !machineryStopped)
		{
			return false;
		}

		return hasPayDirtInTransit() || sackTracker.isCommittedFull(config.blockAtCount());
	}

	/**
	 * Whether there is anything worth saying about the hopper at all. The overlay runs every frame,
	 * so it checks this before working out which of the two problems apply.
	 */
	boolean shouldFlagHopper()
	{
		return machineryStopped || hasPayDirtInTransit();
	}

	/**
	 * @return true when pay-dirt of yours is on the belt, whether or not the belt is moving
	 */
	boolean hasPayDirtInTransit()
	{
		return sackTracker.getInTransit() > 0;
	}

	/**
	 * @return true when the belt has stopped, so pay-dirt put in the hopper would not reach the sack
	 */
	boolean isMachineryStopped()
	{
		return machineryStopped;
	}

	/**
	 * @return true when pay-dirt is stranded on a stopped belt, going nowhere until a strut is fixed
	 */
	boolean hasStuckPayDirt()
	{
		return machineryStopped && sackTracker.getInTransit() > 0;
	}

	/**
	 * The two water wheels drive the conveyor belt, and each is held up by a strut. Water only stops
	 * once both struts are broken — repairing either one starts the belt again.
	 */
	private void updateMachineryState()
	{
		boolean stopped = brokenStruts.size() >= STRUT_COUNT;
		if (stopped == machineryStopped)
		{
			return;
		}

		machineryStopped = stopped;
		log.debug("Machinery stopped: {} ({} broken struts, {} working, {} hoppers tracked)", stopped,
			brokenStruts.size(), workingStruts.size(), hoppers.size());
	}

	private void clearSceneObjects()
	{
		hoppers.clear();
		brokenStruts.clear();
		workingStruts.clear();
		babyMoles.clear();
		machineryStopped = false;
	}

	private void primeTracker()
	{
		sackTracker.reset();
		sackTracker.refreshSack(client);
		sackTracker.refreshInventory(client);
		sackTracker.prime();
	}

	/**
	 * Moves the block count up to the larger sack size once the upgrade is unlocked. A block count of
	 * 108 always follows the upgrade, whether it was left at the default or set there deliberately —
	 * only some other value is treated as a deliberate choice and left alone.
	 */
	private void followCapacityUpgrade()
	{
		if (sackTracker.getCapacity() != SackTracker.SACK_LARGE_SIZE)
		{
			return;
		}

		String stored = configManager.getConfiguration(CONFIG_GROUP, MlmQolConfig.BLOCK_AT_COUNT);
		if (stored != null && !stored.equals(Integer.toString(SackTracker.SACK_SIZE)))
		{
			log.debug("Sack upgrade unlocked but block count is set to {}, leaving it alone", stored);
			return;
		}

		log.debug("Sack upgrade unlocked, raising block count to {}", SackTracker.SACK_LARGE_SIZE);
		configManager.setConfiguration(CONFIG_GROUP, MlmQolConfig.BLOCK_AT_COUNT, SackTracker.SACK_LARGE_SIZE);
	}

	private void updateSackFull()
	{
		if (!inMlm)
		{
			return;
		}

		int blockAt = Math.min(config.blockAtCount(), sackTracker.getCapacity());
		boolean full = sackTracker.isFull(blockAt);
		if (full == sackFull)
		{
			return;
		}

		sackFull = full;
		log.debug("Sack full: {} ({}/{} blocking at {}, {} deposited, {} on the belt, {} carried)", full,
			sackTracker.getUsed(), sackTracker.getCapacity(), blockAt,
			sackTracker.getDeposited(), sackTracker.getInTransit(), sackTracker.getCarriedPayDirt());

		if (config.warnInChat())
		{
			sendChatMessage(full
				? "Sack limit reached (" + sackTracker.getUsed() + "/" + blockAt
					+ ") - mining is blocked until you collect from the sack."
				: "Your sack has room again - mining is re-enabled.");
		}
	}

	/**
	 * Alerts once each time mining stops, whatever stopped it — the vein running out, the sack filling
	 * up, or anything else that interrupts the swing.
	 */
	private void checkMiningStopped()
	{
		Player local = client.getLocalPlayer();
		if (local == null)
		{
			miningIdleTracker.reset();
			return;
		}

		if (!miningIdleTracker.onTick(local.getAnimation()))
		{
			return;
		}

		if (config.playWakeUpSound())
		{
			wakeUpSound.play(config.wakeUpSoundVolume());
		}
	}

	private void sendChatMessage(String message)
	{
		String formatted = new ChatMessageBuilder()
			.append(ChatColorType.HIGHLIGHT)
			.append(message)
			.build();

		chatMessageManager.queue(QueuedMessage.builder()
			.type(ChatMessageType.GAMEMESSAGE)
			.runeLiteFormattedMessage(formatted)
			.build());
	}

	private boolean checkInMlm()
	{
		GameState gameState = client.getGameState();
		if (gameState != GameState.LOGGED_IN && gameState != GameState.LOADING)
		{
			return false;
		}

		WorldView worldView = client.getTopLevelWorldView();
		if (worldView == null)
		{
			return false;
		}

		for (int region : worldView.getMapRegions())
		{
			if (!MOTHERLODE_MAP_REGIONS.contains(region))
			{
				return false;
			}
		}

		return true;
	}
}

package com.mlmqol;

import lombok.Getter;
import net.runelite.api.Client;
import net.runelite.api.ItemContainer;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.VarbitID;

/**
 * Tracks how much room is left in the Motherlode Mine sack.
 *
 * <p>The sack holds 108 pay-dirt, or 189 once the capacity upgrade has been bought from Prospector
 * Percy. Deposited pay-dirt is transmitted in {@link VarbitID#MOTHERLODE_SACK_TRANSMIT}; the upgrade
 * flag lives in {@link VarbitID#MOTHERLODE_BIGGERSACK}.
 *
 * <p>Pay-dirt put into the hopper takes several seconds to travel the conveyor belt before the sack
 * varbit catches up, so pay-dirt that has left the inventory but not yet arrived is tracked
 * separately as "in transit" and counted against the sack immediately. Pay-dirt still in the
 * inventory counts too, since it is already destined for the sack.
 */
class SackTracker
{
	static final int SACK_SIZE = 108;
	static final int SACK_LARGE_SIZE = 189;

	/**
	 * Ticks without the sack growing before in-transit pay-dirt is assumed lost (e.g. dropped rather
	 * than deposited) and written off. The belt delivers continuously, so real gaps are far shorter.
	 */
	private static final int IN_TRANSIT_STALE_TICKS = 50;

	@Getter
	private int deposited;
	@Getter
	private int capacity = SACK_SIZE;
	@Getter
	private int carriedPayDirt;
	@Getter
	private int inTransit;

	private boolean primed;
	private int ticksSinceArrival;

	/**
	 * Reads the capacity upgrade. Safe to call anywhere — the varbit is not tied to being in the
	 * mine, and unlike {@link #refreshSack(Client)} this does not disturb the in-transit bookkeeping.
	 */
	void refreshCapacity(Client client)
	{
		capacity = client.getVarbitValue(VarbitID.MOTHERLODE_BIGGERSACK) == 1 ? SACK_LARGE_SIZE : SACK_SIZE;
	}

	void refreshSack(Client client)
	{
		int previous = deposited;
		deposited = client.getVarbitValue(VarbitID.MOTHERLODE_SACK_TRANSMIT);
		refreshCapacity(client);

		if (primed && deposited > previous)
		{
			// Pay-dirt reached the sack — it is no longer in transit.
			inTransit = Math.max(0, inTransit - (deposited - previous));
			ticksSinceArrival = 0;
		}
	}

	void refreshInventory(Client client)
	{
		ItemContainer inventory = client.getItemContainer(InventoryID.INV);
		int previous = carriedPayDirt;
		carriedPayDirt = inventory == null ? 0 : inventory.count(ItemID.PAYDIRT);

		if (primed && carriedPayDirt < previous)
		{
			// Pay-dirt left the inventory, so it went into the hopper and is now on the belt.
			inTransit += previous - carriedPayDirt;
			ticksSinceArrival = 0;
		}
	}

	/**
	 * Writes off in-transit pay-dirt that never showed up in the sack, so a dropped stack cannot
	 * block mining forever.
	 */
	void onTick()
	{
		if (inTransit == 0)
		{
			return;
		}

		if (++ticksSinceArrival >= IN_TRANSIT_STALE_TICKS)
		{
			inTransit = 0;
			ticksSinceArrival = 0;
		}
	}

	/**
	 * Marks the tracker as holding real values, so subsequent changes are treated as deposits and
	 * arrivals rather than as the initial read.
	 */
	void prime()
	{
		primed = true;
	}

	void reset()
	{
		deposited = 0;
		capacity = SACK_SIZE;
		carriedPayDirt = 0;
		inTransit = 0;
		ticksSinceArrival = 0;
		primed = false;
	}

	/**
	 * @return pay-dirt already committed to the sack: deposited, on the belt, and carried
	 */
	int getUsed()
	{
		return deposited + inTransit + carriedPayDirt;
	}

	/**
	 * Pay-dirt the sack has already taken on: delivered, plus still travelling the belt. Excludes
	 * what is in the inventory, which has somewhere to go and simply hasn't gone yet.
	 */
	int getCommitted()
	{
		return deposited + inTransit;
	}

	/**
	 * @param blockAt the configured pay-dirt count to stop at
	 * @return true when the sack has no room left for another deposit, whatever you are carrying
	 */
	boolean isCommittedFull(int blockAt)
	{
		return getCommitted() >= Math.min(blockAt, capacity);
	}

	/**
	 * @param blockAt the configured pay-dirt count to stop at
	 * @return true when the sack has reached the block count
	 */
	boolean isFull(int blockAt)
	{
		// The real capacity is always a hard ceiling — a block count above it would never trigger.
		return getUsed() >= Math.min(blockAt, capacity);
	}
}

package com.mlmqol;

import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.audio.AudioPlayer;

/**
 * Plays the bundled wake-up sound.
 *
 * <p>Playback opens an audio line and reads the clip, so it is handed to a single-threaded executor
 * rather than run on the client thread. One thread also means a burst of alerts queues up instead of
 * overlapping.
 */
@Slf4j
@Singleton
class WakeUpSound
{
	/** Resolved against this package, so it lives in {@code src/main/resources/com/mlmqol}. */
	private static final String SOUND_FILE = "wake_up.wav";

	private final AudioPlayer audioPlayer;
	private ExecutorService executor;

	@Inject
	WakeUpSound(AudioPlayer audioPlayer)
	{
		this.audioPlayer = audioPlayer;
	}

	void start()
	{
		executor = Executors.newSingleThreadExecutor();
	}

	void shutDown()
	{
		if (executor != null)
		{
			executor.shutdownNow();
			executor = null;
		}
	}

	/**
	 * @param volume 0 (silent, nothing plays) to 100 (the clip's own level)
	 */
	void play(int volume)
	{
		if (executor == null || executor.isShutdown() || volume <= 0)
		{
			return;
		}

		float gain = volumeToGain(volume);
		executor.submit(() ->
		{
			try
			{
				audioPlayer.play(MlmQolPlugin.class, SOUND_FILE, gain);
			}
			catch (Exception e)
			{
				log.debug("Failed to play {}", SOUND_FILE, e);
			}
		});
	}

	/** Maps a 0-100 volume onto the decibel gain {@link AudioPlayer} expects. */
	static float volumeToGain(int volume)
	{
		if (volume <= 0)
		{
			return -80f;
		}

		return 20f * (float) Math.log10(volume / 100f);
	}
}

package com.mlmqol;

import java.awt.Color;
import java.awt.Graphics2D;
import java.util.Collections;
import net.runelite.api.NPC;
import net.runelite.api.Point;
import org.junit.Before;
import org.junit.Test;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.anyInt;
import static org.mockito.ArgumentMatchers.anyString;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

/**
 * Covers the name drawn over the baby mole. Which moles are in the set is the plugin's decision, and
 * is what keeps this to the Motherlode Mine — see MlmQolPluginTest.
 */
public class BabyMoleOverlayTest
{
	private static final String NAME = "Digby";
	private static final int TEXT_X = 40;
	private static final int TEXT_Y = 50;

	private MlmQolPlugin plugin;
	private MlmQolConfig config;
	private Graphics2D graphics;
	private BabyMoleOverlay overlay;

	@Before
	public void setUp()
	{
		plugin = mock(MlmQolPlugin.class);
		config = mock(MlmQolConfig.class);
		graphics = mock(Graphics2D.class);
		overlay = new BabyMoleOverlay(plugin, config);

		NPC mole = mock(NPC.class);
		when(mole.getLogicalHeight()).thenReturn(100);
		when(mole.getCanvasTextLocation(any(), any(), anyInt())).thenReturn(new Point(TEXT_X, TEXT_Y));
		when(plugin.getBabyMoles()).thenReturn(Collections.singleton(mole));

		when(config.nameBabyMole()).thenReturn(true);
		when(config.babyMoleName()).thenReturn(NAME);
		when(config.babyMoleNameColor()).thenReturn(Color.WHITE);
	}

	@Test
	public void theNameIsDrawnOverTheMole()
	{
		overlay.render(graphics);

		verify(graphics).drawString(NAME, TEXT_X, TEXT_Y);
	}

	@Test
	public void nothingIsDrawnWhenTurnedOff()
	{
		when(config.nameBabyMole()).thenReturn(false);

		overlay.render(graphics);

		verify(graphics, never()).drawString(anyString(), anyInt(), anyInt());
	}

	@Test
	public void turnedOffDoesNotEvenWalkTheSceneState()
	{
		// This runs every frame, so the cheap check has to come first.
		when(config.nameBabyMole()).thenReturn(false);

		overlay.render(graphics);

		verify(plugin, never()).getBabyMoles();
	}

	@Test
	public void anEmptyNameDrawsNothing()
	{
		when(config.babyMoleName()).thenReturn("");

		overlay.render(graphics);

		verify(graphics, never()).drawString(anyString(), anyInt(), anyInt());
	}

	@Test
	public void aNameOfNothingButSpacesDrawsNothing()
	{
		when(config.babyMoleName()).thenReturn("   ");

		overlay.render(graphics);

		verify(graphics, never()).drawString(anyString(), anyInt(), anyInt());
	}

	@Test
	public void surroundingSpaceIsTrimmedOffTheName()
	{
